async (page) => {
  const ctx = page.context();
  await ctx.unroute('**/*');
  const ok = /^http:\/\/(localhost|127\.0\.0\.1|\[::1\]):5174(\/|$|\?|#)/;
  await ctx.route('**/*', async (route) => {
    const url = route.request().url();
    const isHttp = url.slice(0, 5) === 'http:' || url.slice(0, 6) === 'https:';
    if (isHttp && !ok.test(url)) return route.abort();
    return route.continue();
  });
  return 'guard reinstalled';
}
